import { query } from '../db.js';

// Callback-style database access. Chapter 5 migrates this to OrderRepository.
export function listOrdersForUser(userId, callback) {
  query('orders', (o) => o.user_id === userId && o.deleted_at === null, callback);
}

export function totalPaidCents(callback) {
  query('orders', (o) => o.status === 'paid' && o.deleted_at === null, (err, rows) => {
    if (err) return callback(err);
    callback(null, rows.reduce((sum, o) => sum + o.total_cents, 0));
  });
}
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { listOrdersForUser, totalPaidCents } from '../src/services/order-service.js';

test('listOrdersForUser returns only that user orders', (t, done) => {
  listOrdersForUser(1, (err, orders) => {
    assert.equal(err, null);
    assert.equal(orders.length, 2);
    assert.ok(orders.every((o) => o.user_id === 1));
    done();
  });
});

test('totalPaidCents counts only paid orders', (t, done) => {
  totalPaidCents((err, total) => {
    assert.equal(err, null);
    assert.equal(total, 4200 + 9900 + 500);
    done();
  });
});
// A router with no framework, so the project has an HTTP surface to survey
// in Chapter 1's rate-limiting example without an Express dependency.
import { listActiveUsers, findUser } from '../services/user-service.js';
import { listOrdersForUser, totalPaidCents } from '../services/order-service.js';
import { uncapturedTotalCents } from '../services/payment-service.js';

export const routes = [
  { method: 'GET', path: '/users', handler: (req, cb) => listActiveUsers(cb) },
  { method: 'GET', path: '/users/:id', handler: (req, cb) => findUser(Number(req.params.id), cb) },
  { method: 'GET', path: '/users/:id/orders', handler: (req, cb) => listOrdersForUser(Number(req.params.id), cb) },
  { method: 'GET', path: '/reports/paid-total', handler: (req, cb) => totalPaidCents(cb) },
  { method: 'GET', path: '/reports/uncaptured-total', handler: (req, cb) => uncapturedTotalCents(cb) },
];

export function listEndpoints() {
  return routes.map((r) => `${r.method} ${r.path}`);
}
import { query } from '../db.js';

export class OrderRepository {
  findByUser(userId) {
    return new Promise((resolve, reject) => {
      query('orders', (o) => o.user_id === userId && o.deleted_at === null,
        (err, rows) => (err ? reject(err) : resolve(rows)));
    });
  }

  findPaid() {
    return new Promise((resolve, reject) => {
      query('orders', (o) => o.status === 'paid' && o.deleted_at === null,
        (err, rows) => (err ? reject(err) : resolve(rows)));
    });
  }
}
import { query, update } from '../db.js';

// The repository pattern the project is migrating toward: promise-based,
// one place per table, no query construction anywhere else.
export class UserRepository {
  findActive() {
    return new Promise((resolve, reject) => {
      query('users', (u) => u.deleted_at === null, (err, rows) =>
        err ? reject(err) : resolve(rows));
    });
  }

  findById(id) {
    return new Promise((resolve, reject) => {
      query('users', (u) => u.id === id, (err, rows) =>
        err ? reject(err) : resolve(rows[0] ?? null));
    });
  }

  softDelete(id, when) {
    return new Promise((resolve, reject) => {
      update('users', id, { deleted_at: when }, (err, row) =>
        err ? reject(err) : resolve(row));
    });
  }
}
// Calls every handler in src/api/routes.js the way the router does, with a
// request object and a callback, and reports whether each one answers.
// The unit tests call service functions directly, so a change to a service's
// signature can pass them while the router can no longer reach it.
// Exits 1 if any route errors or never calls back.
import { routes } from '../src/api/routes.js';

const TIMEOUT_MS = 1500;
let broken = 0;

for (const route of routes) {
  const outcome = await new Promise((resolve) => {
    const timer = setTimeout(() => resolve({ ok: false, text: 'NO RESPONSE (callback never called)' }), TIMEOUT_MS);
    try {
      route.handler({ params: { id: '1' } }, (err, data) => {
        clearTimeout(timer);
        if (err) resolve({ ok: false, text: `error: ${err.message}` });
        else resolve({ ok: true, text: JSON.stringify(data).slice(0, 60) });
      });
    } catch (err) {
      clearTimeout(timer);
      resolve({ ok: false, text: `threw: ${err.message}` });
    }
  });
  if (!outcome.ok) broken += 1;
  console.log(`${outcome.ok ? 'ok  ' : 'FAIL'}  ${route.method} ${route.path} -> ${outcome.text}`);
}

console.log(broken ? `${broken} of ${routes.length} routes broken` : `all ${routes.length} routes respond`);
process.exit(broken ? 1 : 0);

